export function getMockSpots(city: 'nyc' | 'sf' | 'fortlee'): SpotWithDetails[] {
  if (city === 'fortlee') {
    return FORT_LEE_SPOTS;
  }
  return MOCK_SPOTS.filter(s => s.city === city);
}

export function getMockSpotById(id: string): SpotWithDetails | null {
  const fromMain = MOCK_SPOTS.find(s => s.id === id);
  if (fromMain) return fromMain;
  return FORT_LEE_SPOTS.find(s => s.id === id) || null;
}
